# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# simulate_fims ----
## Setup ----
# data_big without fleet1's age composition in year 2, so FIMSFrame() fills
# its 12 ages with -999. The model is not optimized: simulate_fims() draws
# from the predictions at the values in the fit, here the starting values.
data_missing <- data_big |>
  dplyr::filter(!(fleet == "fleet1" & type == "age_comp" & timing == 2)) |>
  FIMSFrame()
default_parameters <- setup_default_parameters(data_missing)
fit <- default_parameters |>
  initialize_fims(data = data_missing) |>
  fit_fims(optimize = FALSE)
input_data <- get_data(data_missing)
number_of_simulations <- 50
simulations <- withr::with_seed(
  1,
  simulate_fims(fit, number_of_simulations = number_of_simulations)
)

## IO correctness ----
test_that("`simulate_fims()` works with correct inputs", {
  first_data <- simulations[[1]][["data"]]
  #' @description Test that `simulate_fims()` returns 1 element per simulated data set.
  expect_length(
    object = simulations,
    n = number_of_simulations
  )
  #' @description Test that each simulated data set has the rows and columns of the input data.
  expect_equal(
    object = dim(first_data),
    expected = dim(input_data)
  )
  #' @description Test that `simulate_fims()` changes only the observed column of the input data.
  expect_equal(
    object = dplyr::select(first_data, -observed),
    expected = dplyr::select(input_data, -observed)
  )
  #' @description Test that `simulate_fims()` changes the observed values of the data it simulates.
  expect_false(isTRUE(all.equal(
    dplyr::filter(first_data, type == "index")[["observed"]],
    dplyr::filter(input_data, type == "index")[["observed"]]
  )))
  #' @description Test that `simulate_fims()` keeps data that are not simulated, e.g., weight at age, as they were.
  expect_equal(
    object = dplyr::filter(first_data, type == "weight_at_age"),
    expected = dplyr::filter(input_data, type == "weight_at_age")
  )
})

test_that("`simulate_fims()` draws data from the model's predictions", {
  # The survey index is lognormal with an sdlog of sqrt(log(1 + 0.2^2)), so
  # (log(simulated) - log(expected)) / sdlog is standard normal.
  index_sdlog <- sqrt(log(1 + 0.2^2))
  standardized_index <- unlist(lapply(simulations, function(simulation) {
    simulated <- simulation[["data"]] |>
      dplyr::filter(type == "index", fleet == "survey1") |>
      dplyr::arrange(timing)
    log_expected <- simulation[["truth"]][["fleets"]][["survey1"]][[
      "log_index_expected"
    ]]
    (log(simulated[["observed"]]) - log_expected) / index_sdlog
  }))
  #' @description Test that the simulated survey index has a mean log residual near 0, within 0.05 standard deviations over 50 times 30 draws.
  expect_lt(
    object = abs(mean(standardized_index)),
    expected = 0.05
  )
  #' @description Test that the simulated survey index has log residuals with a standard deviation near the sdlog in the data, within 10%.
  expect_lt(
    object = abs(stats::sd(standardized_index) - 1),
    expected = 0.1
  )

  # Age compositions are multinomial proportions, so each year sums to 1 and
  # their mean over many data sets is the expected proportion.
  survey_age_comp <- lapply(simulations, function(simulation) {
    simulation[["data"]] |>
      dplyr::filter(type == "age_comp", fleet == "survey1") |>
      dplyr::arrange(timing, age) |>
      dplyr::pull(observed)
  })
  #' @description Test that each year of a simulated age composition sums to 1.
  expect_equal(
    object = rowSums(matrix(survey_age_comp[[1]], ncol = 12, byrow = TRUE)),
    expected = rep(1, 30)
  )
  mean_proportion <- Reduce(`+`, survey_age_comp) / number_of_simulations
  expected_proportion <- simulations[[1]][["truth"]][["fleets"]][[
    "survey1"
  ]][["agecomp_proportion"]]
  # With a sample size of 200 and 50 data sets, the standard error of a mean
  # proportion is at most sqrt(0.25 / (200 * 50)), 0.005.
  #' @description Test that the mean simulated survey age composition is within 0.025 of the expected proportion at every year and age.
  expect_lt(
    object = max(abs(mean_proportion - as.vector(t(expected_proportion)))),
    expected = 0.025
  )
})

## Edge handling ----
test_that("`simulate_fims()` returns correct outputs for edge cases", {
  missing_rows <- function(data) {
    dplyr::filter(data, fleet == "fleet1", type == "age_comp", timing == 2)
  }
  #' @description Test that `simulate_fims()` leaves the 12 missing age-composition values as -999.
  expect_equal(
    object = missing_rows(simulations[[1]][["data"]])[["observed"]],
    expected = rep(-999, 12)
  )

  # With random effects kept, the recruitment deviations stay at their
  # values in the fit, 0. When they are redrawn, they are Normal(0, sd).
  recruitment_sd <- default_parameters |>
    dplyr::filter(module_name == "Recruitment", label == "log_sd") |>
    dplyr::pull(value) |>
    exp()
  #' @description Test that `simulate_fims()` keeps the recruitment deviations at their values in the fit, 0, by default.
  expect_equal(
    object = as.vector(
      simulations[[1]][["parameters"]][["Recruitment.log_devs"]]
    ),
    expected = rep(0, 29)
  )
  redrawn <- withr::with_seed(
    2,
    simulate_fims(fit, number_of_simulations, random_effects = "redraw")
  )
  redrawn_deviations <- unlist(lapply(redrawn, function(simulation) {
    simulation[["parameters"]][["Recruitment.log_devs"]]
  }))
  #' @description Test that redrawn recruitment deviations have a mean within 0.1 of 0 over 50 times 29 draws.
  expect_lt(
    object = abs(mean(redrawn_deviations)),
    expected = 0.1
  )
  #' @description Test that redrawn recruitment deviations have a standard deviation within 10% of the recruitment sd.
  expect_lt(
    object = abs(stats::sd(redrawn_deviations) / recruitment_sd - 1),
    expected = 0.1
  )
  #' @description Test that `simulate_fims()` with redrawn random effects keeps the fixed effects, e.g., log_rzero, at their values in the fit.
  expect_equal(
    object = redrawn[[1]][["parameters"]][["Recruitment.log_rzero"]],
    expected = simulations[[1]][["parameters"]][["Recruitment.log_rzero"]]
  )
})

test_that("`simulate_fims()` draws normal compositions cell by cell", {
  # survey1's age compositions as counts with a normal likelihood, so each
  # simulated cell is centered on its own expected value.
  normal_comps <- data_big |>
    dplyr::mutate(
      is_survey_comp = type == "age_comp" & fleet == "survey1",
      observed = dplyr::if_else(is_survey_comp, observed * 200, observed),
      unit = dplyr::if_else(is_survey_comp, "number", unit),
      uncertainty = dplyr::if_else(
        is_survey_comp, "~ dnorm(mean = agecomp_expected, sd = 1)", uncertainty
      )
    ) |>
    dplyr::select(-"is_survey_comp") |>
    FIMSFrame()
  normal_fit <- setup_default_parameters(normal_comps) |>
    initialize_fims(data = normal_comps) |>
    fit_fims(optimize = FALSE)
  expected <- get_estimates(normal_fit) |>
    dplyr::filter(label == "agecomp_expected", fleet == "survey1") |>
    dplyr::select(timing = "year_i", "age", "expected")
  simulated_mean <- withr::with_seed(
    1,
    simulate_fims(normal_fit, number_of_simulations = 50)
  ) |>
    purrr::map(\(simulation) simulation[["data"]]) |>
    dplyr::bind_rows() |>
    dplyr::filter(type == "age_comp", fleet == "survey1") |>
    dplyr::summarize(observed = mean(observed), .by = c("timing", "age")) |>
    dplyr::inner_join(expected, by = c("timing", "age"))
  #' @description Test that the mean of 50 normal composition draws in each cell is within 4 standard errors (sd 1) of that cell's expected value.
  expect_lt(
    object = max(abs(simulated_mean[["observed"]] - simulated_mean[["expected"]])),
    expected = 4 / sqrt(50)
  )
})

## Error handling ----
test_that("`simulate_fims()` returns correct error messages", {
  # A log_r process varies around the stock-recruit curve, which depends on
  # the recruitment it drives, so it cannot be drawn first.
  log_r_fit <- default_parameters |>
    dplyr::mutate(
      label = dplyr::if_else(label == "log_devs", "log_r", label),
      value = dplyr::if_else(label == "log_r", log(1e6), value)
    ) |>
    initialize_fims(data = data_missing) |>
    fit_fims(optimize = FALSE)
  #' @description Test that `simulate_fims()` errors when asked to redraw log_r, whose mean depends on the population.
  expect_error(
    object = simulate_fims(log_r_fit, random_effects = "redraw"),
    regexp = "Cannot redraw"
  )
  #' @description Test that `simulate_fims()` errors for a `random_effects` value other than "keep" or "redraw".
  expect_error(
    object = simulate_fims(fit, random_effects = "resample"),
    regexp = "should be one of"
  )
})

# run_fims_self_test ----
## Setup ----
# No setup required.

## IO correctness ----
test_that("`run_fims_self_test()` works with correct inputs", {
  # Each data set is refit, which takes about 10 seconds.
  testthat::skip_if(
    Sys.getenv("RUN_SLOW_TESTS") != "true",
    "Skipping: RUN_SLOW_TESTS is not set to true."
  )
  # The refits may warn about their gradients. The test checks the size of
  # the gradient instead.
  self_test <- suppressWarnings(
    run_fims_self_test(fit, number_of_simulations = 2)
  )
  #' @description Test that `run_fims_self_test()` returns 1 row per simulated data set.
  expect_equal(
    object = self_test[["simulation"]],
    expected = 1:2
  )
  #' @description Test that every refit in `run_fims_self_test()` converges.
  expect_true(all(self_test[["converged"]]))
  # The data are drawn from the model being refit, and catch has a CV of
  # 0.01, so the refits should recover spawning biomass in every year and
  # mean recruitment. Draws from the wrong scale or the wrong expected values
  # would miss by far more than 25%.
  #' @description Test that the refits recover spawning biomass within 25% of the truth in every year.
  expect_lt(
    object = max(self_test[["max_abs_relative_error_spawning_biomass"]]),
    expected = 0.25
  )
  #' @description Test that the refits recover mean recruitment within 25% of the truth.
  expect_lt(
    object = max(abs(self_test[["relative_error_mean_recruitment"]])),
    expected = 0.25
  )
  #' @description Test that `run_fims_self_test()` with the same seed returns the same data sets, so the same results.
  expect_equal(
    object = suppressWarnings(
      run_fims_self_test(fit, number_of_simulations = 1)
    ),
    expected = self_test[1, ]
  )
})

